// Shared deep-link state. appstore:// requests navigation through the same
// App Store-style Search tab and product detail destination as an in-app tap.
final class KsignCloneStoreNavigation: ObservableObject {
    static let shared = KsignCloneStoreNavigation()

    // A monotonically increasing event ID is used instead of a Boolean. A Boolean
    // can miss repeated URL opens when SwiftUI has not finished updating the prior route.
    @Published private(set) var pubgProductPageRequestID: UInt64 = 0
    private var lastConsumedPUBGRequestID: UInt64 = 0

    private init() {}

    func requestPUBGProductPage() {
        pubgProductPageRequestID &+= 1
    }

    func consumePUBGProductPageRequest(_ requestID: UInt64) -> Bool {
        guard requestID != 0, requestID != lastConsumedPUBGRequestID else { return false }
        lastConsumedPUBGRequestID = requestID
        return true
    }
}

// MARK: - Main Tab View

struct KsignCloneStoreView: View {
    @StateObject private var data = KsignCloneStoreData()
    @StateObject private var deepLinkNavigation = KsignCloneStoreNavigation.shared
    @State private var selectedStoreTab = 0
    @State private var showPUBGProductPage = false
    @State private var keyboardVisible = false

    @ViewBuilder
    private var selectedStoreContent: some View {
        switch selectedStoreTab {
        case 0:
            KsignCloneTodayView(data: data)
        case 1:
            KsignCloneAppsView(title: "Games", apps: data.games)
        case 2:
            KsignCloneAppsView(title: "Apps", apps: (data.games.first(where: { $0.name == "PUBG MOBILE" }).map { [$0] } ?? []) + data.featuredApps)
        case 3:
            KsignCloneArcadeView()
        default:
            KsignCloneSearchView(data: data, showPUBGProductPage: $showPUBGProductPage)
        }
    }

    private func handlePUBGProductPageRequest(_ requestID: UInt64) {
        guard deepLinkNavigation.consumePUBGProductPageRequest(requestID) else { return }
        selectedStoreTab = 4
        showPUBGProductPage = false
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
            guard deepLinkNavigation.pubgProductPageRequestID == requestID else { return }
            showPUBGProductPage = true
        }
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // Do not nest another TabView here: its native tab bar stacked with the
            // custom App Store bar and produced the duplicate-panel bug.
            selectedStoreContent
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                // The matched-geometry spring belongs to the tab bar only. Do not
                // animate the page subtree when selection changes; this avoids
                // old/new pages ghosting over one another.
                .transaction { transaction in transaction.animation = nil }

            if !keyboardVisible {
                KsignCloneFloatingTabBar(selection: $selectedStoreTab)
                    .padding(.horizontal, 24)
                    .padding(.bottom, 8)
                    .zIndex(20)
                    .transition(.opacity)
            }

            // Shared visual install-confirmation sheet; placed at the root so the
            // same animation works from Today, Games, Apps, Search and product pages.
            KsignCloneInstallPromptOverlay()
                .zIndex(1000)
        }
        .background(Color.black.ignoresSafeArea())
        .toolbar(.hidden, for: .tabBar)
        .preferredColorScheme(.dark)
        .onReceive(deepLinkNavigation.$pubgProductPageRequestID) { handlePUBGProductPageRequest($0) }
        .onReceive(NotificationCenter.default.publisher(for: UIResponder.keyboardWillShowNotification)) { _ in
            withAnimation(.easeOut(duration: 0.15)) { keyboardVisible = true }
        }
        .onReceive(NotificationCenter.default.publisher(for: UIResponder.keyboardWillHideNotification)) { _ in
            withAnimation(.easeOut(duration: 0.15)) { keyboardVisible = false }
        }
        .onAppear { handlePUBGProductPageRequest(deepLinkNavigation.pubgProductPageRequestID) }
    }
}

private struct KsignCloneFloatingTabBar: View {
    @Binding var selection: Int
    @Namespace private var selectionAnimation

    private let tabs: [(title: String, symbol: String)] = [
        ("Today", "today-outline"),
        ("Games", "rocket.fill"),
        ("Apps", "square.stack.3d.up.fill"),
        ("Arcade", "arcade-custom"),
        ("Search", "magnifyingglass")
    ]
    private let accent = Color(red: 0.18, green: 0.61, blue: 1.0)

    var body: some View {
        HStack(spacing: 1) {
            ForEach(Array(tabs.enumerated()), id: \.offset) { index, tab in
                Button {
                    guard selection != index else { return }
                    UIImpactFeedbackGenerator(style: .soft).impactOccurred()
                    withAnimation(.spring(response: 0.42, dampingFraction: 0.78, blendDuration: 0.10)) {
                        selection = index
                    }
                } label: {
                    VStack(spacing: 5) {
                        tabIcon(tab.symbol, isSelected: selection == index)
                            .frame(height: 36)
                        Text(tab.title)
                            .font(.system(size: 14.5, weight: selection == index ? .semibold : .medium, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.82)
                    }
                    .foregroundStyle(selection == index ? accent : Color.white.opacity(0.98))
                    .frame(maxWidth: .infinity)
                    .frame(height: 70)
                    .contentShape(RoundedRectangle(cornerRadius: 36, style: .continuous))
                    .background {
                        if selection == index {
                            Capsule()
                                .fill(Color.white.opacity(0.115))
                                .overlay {
                                    Capsule().stroke(Color.white.opacity(0.055), lineWidth: 0.8)
                                }
                                .matchedGeometryEffect(id: "appstore-tab-selection", in: selectionAnimation)
                                .padding(.horizontal, -7)
                                .padding(.vertical, 1)
                        }
                    }
                    .scaleEffect(selection == index ? 1.0 : 0.985)
                }
                .buttonStyle(KsignCloneGlassTabButtonStyle())
                .accessibilityLabel(tab.title)
                .accessibilityAddTraits(selection == index ? .isSelected : [])
            }
        }
        .padding(5)
        .frame(height: 80)
        .background {
            // Layered material, dark tint, and edge highlights recreate the
            // Liquid Glass pill from the reference while remaining readable.
            Capsule(style: .continuous)
                .fill(.ultraThinMaterial)
                .environment(\.colorScheme, .dark)
                .overlay {
                    Capsule(style: .continuous)
                        .fill(Color(red: 0.075, green: 0.078, blue: 0.085).opacity(0.68))
                }
                .overlay {
                    Capsule(style: .continuous)
                        .fill(LinearGradient(
                            colors: [Color.white.opacity(0.105), Color.white.opacity(0.025), Color.black.opacity(0.12)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        ))
                }
                .overlay {
                    Capsule(style: .continuous)
                        .stroke(LinearGradient(
                            colors: [Color.white.opacity(0.28), Color.white.opacity(0.10), Color.white.opacity(0.18)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        ), lineWidth: 1.15)
                }
                .shadow(color: .black.opacity(0.38), radius: 18, x: 0, y: 7)
        }
        .overlay(alignment: .top) {
            Capsule()
                .fill(LinearGradient(colors: [Color.white.opacity(0.22), Color.white.opacity(0.015)], startPoint: .leading, endPoint: .trailing))
                .frame(height: 1)
                .padding(.horizontal, 34)
                .padding(.top, 1.5)
                .allowsHitTesting(false)
        }
        .accessibilityElement(children: .contain)
    }

    @ViewBuilder
    private func tabIcon(_ symbol: String, isSelected: Bool) -> some View {
        switch symbol {
        case "today-outline":
            ZStack {
                RoundedRectangle(cornerRadius: 5.5, style: .continuous)
                    .stroke(isSelected ? accent : Color.white, lineWidth: 3.2)
                    .frame(width: 25, height: 34)
                VStack(alignment: .leading, spacing: 4) {
                    Capsule().fill(isSelected ? accent : Color.white).frame(width: 17, height: 2.7)
                    Capsule().fill(isSelected ? accent : Color.white).frame(width: 18, height: 2.7)
                    RoundedRectangle(cornerRadius: 2, style: .continuous)
                        .fill(isSelected ? accent.opacity(0.95) : Color.white)
                        .frame(width: 17, height: 10)
                }
                .offset(y: 3)
            }
            .frame(width: 41, height: 36)
        case "arcade-custom":
            ZStack {
                RoundedRectangle(cornerRadius: 7, style: .continuous)
                    .stroke(Color.white, lineWidth: 3.2)
                    .frame(width: 45, height: 23)
                    .offset(y: 6)
                Capsule().fill(Color.white).frame(width: 3.2, height: 10).offset(x: -11, y: -5)
                Circle().fill(Color.white).frame(width: 8, height: 8).offset(x: -11, y: -14)
                HStack(spacing: 4.0) {
                    ForEach(0..<4, id: \.self) { _ in Circle().fill(Color.white).frame(width: 4.8, height: 4.8) }
                }
                .offset(x: 6, y: 1)
                HStack(spacing: 4.0) {
                    ForEach(0..<4, id: \.self) { _ in Circle().fill(Color.white).frame(width: 4.8, height: 4.8) }
                }
                .offset(x: 6, y: 10)
            }
            .frame(width: 47, height: 41)
        default:
            Image(systemName: symbol)
                .font(.system(size: symbol == "magnifyingglass" ? 37 : 38, weight: .medium))
                .symbolRenderingMode(.hierarchical)
                .foregroundStyle(isSelected ? accent : Color.white)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

